{
  "vulnerable_symbols": [],
  "trigger": "当 Flask 应用位于会缓存带 Cookie 响应的代理后，启用永久会话且请求中不读写 session 时，刷新 session 缺少 Vary: Cookie，导致代理可能缓存并转发他人 session cookie。",
  "preconditions": [
    "应用部署在不剥离 Cookie 或忽略带 Cookie 响应的缓存代理之后",
    "应用设置 session.permanent = True",
    "请求处理过程中未访问或修改 session",
    "SESSION_REFRESH_EACH_REQUEST 启用（默认）",
    "响应未设置 Cache-Control: private 或 no-cache 等禁止缓存头"
  ],
  "exploit_evidence": [
    {
      "src": 3,
      "kind": "poc",
      "quote": "EIP currently links 1 repository PoC and 1 lab environment to CVE-2023-30861."
    },
    {
      "src": 5,
      "kind": "poc",
      "quote": "本项目是用于复现Flask的CVE-2023-30861漏洞的PoC。"
    }
  ],
  "fixed_version": "2.2.5, 2.3.2",
  "summary_zh": "Flask 刷新永久会话时缺少 Vary: Cookie，代理可能缓存并转发他人 session cookie，需升级并设置缓存头。"
}
